import pytest

from borgstore.store import Store


@pytest.fixture()
def nested_store(tmp_path):
    store = Store(url=tmp_path.as_uri(), levels={"objects/": [1]})
    store.create()
    try:
        yield store
    finally:
        store.destroy()


def test_list_partitions_normal_and_soft_deleted_objects(nested_store):
    # Use nesting so filtering is verified for objects found via recursive list().
    normal_keys = {"aa000001", "bb000002"}
    deleted_keys = {"cc000003", "dd000004"}

    with nested_store as store:
        for key in normal_keys | deleted_keys:
            store.store(f"objects/{key}", key.encode())

        for key in deleted_keys:
            store.move(f"objects/{key}", delete=True)

        # False (including the default) must expose only live objects.
        normal_names = {item.name for item in store.list("objects", deleted=False)}
        default_names = {item.name for item in store.list("objects")}
        assert normal_names == normal_keys
        assert default_names == normal_keys
        assert all(not name.endswith(".del") for name in normal_names)

        # True must expose only soft-deleted objects, retaining their marker so
        # callers can distinguish them from regular objects.
        deleted_names = {item.name for item in store.list("objects", deleted=True)}
        assert deleted_names == {f"{key}.del" for key in deleted_keys}
        assert all(name.endswith(".del") for name in deleted_names)

        # Once every remaining object is soft-deleted, the two views remain
        # disjoint rather than deleted=True falling back to all objects.
        for key in normal_keys:
            store.move(f"objects/{key}", delete=True)

        assert list(store.list("objects", deleted=False)) == []
        assert {item.name for item in store.list("objects", deleted=True)} == {
            f"{key}.del" for key in normal_keys | deleted_keys
        }

import pytest

from ucumvert import PintUcumRegistry, ucum_preprocessor


@pytest.fixture(scope="module")
def ureg():
    return PintUcumRegistry()


@pytest.mark.parametrize(
    ("ucum_code", "scale"),
    [
        ("m[IU]/L", 1e-3),
        ("k[IU]/L", 1e3),
    ],
)
def test_prefixed_international_unit_per_liter_has_the_correct_scale(
    ureg, ucum_code, scale
):
    """A UCUM prefix must modify [IU], not become a separate unit."""
    quantity = ureg.from_ucum(ucum_code)

    converted = quantity.to("international_unit / liter")

    assert converted.magnitude == pytest.approx(scale)


