    assert converted.magnitude == pytest.approx(scale)


def test_prefixes_on_international_units_and_liters_are_applied_independently(ureg):
    # milli-IU per milli-liter is exactly IU per liter. This ensures that the
    # leading "m" is not interpreted as a meter.
    quantity = ureg.from_ucum("m[IU]/mL")

    converted = quantity.to("international_unit / liter")

    assert converted.magnitude == pytest.approx(1)


