    """The documented preprocessor workflow must produce parseable Pint input."""
    registry = PintUcumRegistry()
    registry.preprocessors.append(ucum_preprocessor)

    quantity = registry(ucum_code).to("international_unit / liter")

    assert quantity.magnitude == pytest.approx(scale)

