from ucumvert import PintUcumRegistry, UcumToPintTransformer, ucum_preprocessor
from ucumvert.parser import get_ucum_parser


@pytest.mark.parametrize(
    ("ucum_code", "expected_unit", "factor"),
    [
        ("m[IU]/L", "milliinternational_unit / liter", 1e-3),
        ("k[IU]/L", "kilointernational_unit / liter", 1e3),
