    ucum_code, expected_unit, factor
):
    """A UCUM prefix must apply to [IU], rather than to a Pint base unit."""
    ureg = PintUcumRegistry()
    result = UcumToPintTransformer(ureg=ureg).transform(
        get_ucum_parser().parse(ucum_code)
    )

    assert str(result.units) == expected_unit
    assert result.to("international_unit / liter").magnitude == pytest.approx(factor)


