from abc import abstractmethod
from typing import Protocol

from dishka import Provider, Scope, WithParents, make_container, provide_all


def test_provide_all_withparents_aliases_protocol_to_implementation() -> None:
    """The exact reported case must register the protocol as an alias."""

    class MyProtocol(Protocol):
        @abstractmethod
        def __call__(self, data: bytes) -> bytes: ...

    class MyImpl(MyProtocol):
        def __call__(self, data: bytes) -> bytes:
            return b"handled:" + data

    class MyProvider(Provider):
        scope = Scope.REQUEST
        interactors = provide_all(WithParents[MyImpl])

    container = make_container(MyProvider())

    with container() as request_container:
        implementation = request_container.get(MyImpl)
        protocol = request_container.get(MyProtocol)

        assert implementation is protocol
        assert protocol(b"payload") == b"handled:payload"


def test_provide_all_withparents_does_not_create_independent_parent_factories() -> None:
    """WithParents must retain its normal alias behavior inside provide_all.

    Constructing Parent directly would require an unavailable dependency.  The
    container can only resolve Parent when it is an alias for Child.
    """

    class Parent:
        def __init__(self, unavailable_dependency: str) -> None:
            self.unavailable_dependency = unavailable_dependency

    class Child(Parent):
        def __init__(self) -> None:
            self.value = "child"

    class Unrelated:
        pass

    class MyProvider(Provider):
        scope = Scope.APP
        dependencies = provide_all(WithParents[Child], Unrelated)

    container = make_container(MyProvider())

    child = container.get(Child)
    parent = container.get(Parent)

    assert parent is child
    assert isinstance(parent, Child)
    assert parent.value == "child"
    assert isinstance(container.get(Unrelated), Unrelated)


def test_provide_all_supports_several_withparents_entries() -> None:
    """Unpacking one WithParents value must not affect other entries."""

    class FirstParent:
        pass

    class FirstChild(FirstParent):
        pass

    class SecondParent:
        pass

    class SecondChild(SecondParent):
        pass

    class MyProvider(Provider):
        scope = Scope.APP
        dependencies = provide_all(
            WithParents[FirstChild],
            WithParents[SecondChild],
        )

    container = make_container(MyProvider())

    first_child = container.get(FirstChild)
    second_child = container.get(SecondChild)

    assert container.get(FirstParent) is first_child
    assert container.get(SecondParent) is second_child
    assert first_child is not second_child

