from dishka import Provider, Scope, WithParents, make_container, provide_all


def test_provide_all_accepts_withparents_for_protocol_implementation():
    class MyProtocol(Protocol):
        @abstractmethod
        def __call__(self, data: bytes) -> bytes: ...

    class MyImpl(MyProtocol):
        def __call__(self, data: bytes) -> bytes:
            return data[::-1]

    class MyProvider(Provider):
        scope = Scope.REQUEST
        interactors = provide_all(WithParents[MyImpl])

    provider = MyProvider()

    # The important regression is that the ProvideMultiple marker returned by
    # WithParents is expanded, rather than treated as a factory itself.
    provided_types = [factory.provides.type_hint for factory in provider.factories]
    assert provided_types == [MyImpl, MyProtocol]


def test_provide_all_withparents_registers_each_concrete_parent_factory():
    class Root:
        pass

    class Parent(Root):
        pass

    class Child(Parent):
        pass

    class MyProvider(Provider):
        scope = Scope.APP
        dependencies = provide_all(WithParents[Child])

    container = make_container(MyProvider())

    child = container.get(Child)
    parent = container.get(Parent)
    root = container.get(Root)

    assert isinstance(child, Child)
    assert isinstance(parent, Parent)
    assert isinstance(root, Root)


def test_provide_all_supports_withparents_alongside_regular_and_multiple_types():
    class FirstParent:
        pass

    class FirstChild(FirstParent):
        pass

    class SecondParent:
        pass

    class SecondChild(SecondParent):
        pass

    class Unrelated:
        pass

    class MyProvider(Provider):
        scope = Scope.APP
        dependencies = provide_all(
            WithParents[FirstChild],
            Unrelated,
            WithParents[SecondChild],
        )

    container = make_container(MyProvider())

    assert isinstance(container.get(FirstChild), FirstChild)
    assert isinstance(container.get(FirstParent), FirstParent)
    assert isinstance(container.get(SecondChild), SecondChild)
    assert isinstance(container.get(SecondParent), SecondParent)
    assert isinstance(container.get(Unrelated), Unrelated)

