def test_provide_all_with_parents_keeps_parent_aliases_for_protocol():
    class Handler(Protocol):
        @abstractmethod
        def __call__(self, data: bytes) -> bytes:
            pass

    class HandlerImplementation(Handler):
        def __call__(self, data: bytes) -> bytes:
            return data[::-1]

    class TestProvider(Provider):
        scope = Scope.REQUEST
        handlers = provide_all(WithParents[HandlerImplementation])

    container = make_container(TestProvider())

    with container() as request_container:
        implementation = request_container.get(HandlerImplementation)
        handler = request_container.get(Handler)

        # WithParents must provide the parent through the implementation, not
        # register the abstract protocol as a constructor factory.
        assert handler is implementation
        assert handler(b"dishka") == b"akhsid"


def test_provide_all_with_parents_preserves_alias_semantics_when_mixed():
    class Base:
        pass

    class Implementation(Base):
        pass

    class Unrelated:
        pass

    class TestProvider(Provider):
        scope = Scope.APP
        dependencies = provide_all(WithParents[Implementation], Unrelated)

    container = make_container(TestProvider())

    implementation = container.get(Implementation)

    # `provide_all` must accept the WithParents marker without changing what
    # WithParents means: parent keys are aliases to the concrete object.
    assert container.get(Base) is implementation
    assert isinstance(container.get(Unrelated), Unrelated)

from typing import Protocol

from dishka import Provider, Scope, WithParents, make_container, provide_all


def test_provide_all_with_parents_creates_aliases_for_protocol_parents():
    class Parent(Protocol):
        def process(self, value: str) -> str: ...

    class Implementation(Parent):
        created = 0

        def __init__(self) -> None:
            type(self).created += 1

        def process(self, value: str) -> str:
            return value.upper()

    class TestProvider(Provider):
        scope = Scope.REQUEST
        implementations = provide_all(WithParents[Implementation])

    container = make_container(TestProvider())

    with container() as request_container:
        implementation = request_container.get(Implementation)
        parent = request_container.get(Parent)

        # A parent protocol cannot be constructed. WithParents must register
        # it as an alias of the implementation factory.
        assert parent is implementation
        assert parent.process("dishka") == "DISHKA"
        assert Implementation.created == 1


def test_provide_all_with_parents_preserves_aliases_when_mixed_with_classes():
    class FirstParent:
        pass

    class SecondParent:
        pass

    class Child(FirstParent, SecondParent):
        created = 0

        def __init__(self) -> None:
            type(self).created += 1

    class Independent:
        pass

    class TestProvider(Provider):
        scope = Scope.APP
        dependencies = provide_all(WithParents[Child], Independent)

    container = make_container(TestProvider())

    child = container.get(Child)

    assert container.get(FirstParent) is child
    assert container.get(SecondParent) is child
    assert isinstance(container.get(Independent), Independent)
    assert Child.created == 1


def test_provider_instance_provide_all_supports_with_parents():
    class Parent:
        pass

    class Child(Parent):
        created = 0

        def __init__(self) -> None:
            type(self).created += 1

    provider = Provider(scope=Scope.APP)
    provider.provide_all(WithParents[Child])

    container = make_container(provider)

    child = container.get(Child)
    assert container.get(Parent) is child
    assert Child.created == 1

