    def __call__(self, data: bytes) -> bytes: ...


class BaseService:
    def name(self) -> str:
        return "base"


class ConcreteService(BaseService, CallableProtocol):
    def __call__(self, data: bytes) -> bytes:
        return data.upper()


class SecondaryProtocol(Protocol):
    def secondary(self) -> str: ...


class MultiInterfaceService(CallableProtocol, SecondaryProtocol):
    def __call__(self, data: bytes) -> bytes:
        return data[::-1]

    def secondary(self) -> str:
        return "secondary"


def test_provide_all_with_parents_registers_concrete_class_and_parents() -> None:
    class TestProvider(Provider):
        scope = Scope.APP
        services = provide_all(WithParents[ConcreteService])

    container = make_container(TestProvider())

    concrete = container.get(ConcreteService)
    as_base = container.get(BaseService)
    as_protocol = container.get(CallableProtocol)

    assert isinstance(concrete, ConcreteService)
    assert concrete(b"hello") == b"HELLO"
    assert as_base is concrete
    assert as_protocol is concrete


def test_provide_all_with_parents_works_at_request_scope() -> None:
    class TestProvider(Provider):
        scope = Scope.REQUEST
        services = provide_all(WithParents[ConcreteService])

    container = make_container(TestProvider())

    with container() as request_container:
        concrete = request_container.get(ConcreteService)

        assert request_container.get(BaseService) is concrete
        assert request_container.get(CallableProtocol) is concrete


def test_provide_all_with_parents_supports_multiple_parent_interfaces() -> None:
    class TestProvider(Provider):
        scope = Scope.APP
        services = provide_all(WithParents[MultiInterfaceService])

    container = make_container(TestProvider())

    service = container.get(MultiInterfaceService)

    assert container.get(CallableProtocol) is service
    assert container.get(SecondaryProtocol) is service
    assert service(b"abc") == b"cba"
    assert service.secondary() == "secondary"


def test_provide_all_accepts_with_parents_alongside_regular_classes() -> None:
    class PlainService:
        pass

    class TestProvider(Provider):
        scope = Scope.APP
        services = provide_all(WithParents[ConcreteService], PlainService)

    container = make_container(TestProvider())

    concrete = container.get(ConcreteService)

    assert container.get(BaseService) is concrete
    assert container.get(CallableProtocol) is concrete
    assert isinstance(container.get(PlainService), PlainService)

from abc import abstractmethod
from typing import Protocol

from dishka import Provider, Scope, WithParents, make_container, provide_all


def test_provide_all_with_parents_registers_concrete_class_and_protocol_alias():
    class MyProtocol(Protocol):
        @abstractmethod
        def __call__(self, data: bytes) -> bytes: ...

    class MyImpl(MyProtocol):
        def __call__(self, data: bytes) -> bytes:
            return data + b"!"

    class MyProvider(Provider):
        scope = Scope.APP
        interactors = provide_all(WithParents[MyImpl])

    container = make_container(MyProvider())

    implementation = container.get(MyImpl)
    protocol = container.get(MyProtocol)

    assert isinstance(implementation, MyImpl)
    assert protocol is implementation
    assert protocol(b"data") == b"data!"


def test_provide_all_with_parents_handles_multiple_parents_and_other_sources():
    class FirstParent(Protocol):
        def first(self) -> str: ...

    class SecondParent(Protocol):
        def second(self) -> str: ...

    class Implementation(FirstParent, SecondParent):
        def first(self) -> str:
            return "first"

        def second(self) -> str:
            return "second"

    class Unrelated:
        pass

    class MyProvider(Provider):
        scope = Scope.APP
        registrations = provide_all(WithParents[Implementation], Unrelated)

    container = make_container(MyProvider())

    implementation = container.get(Implementation)
    first_parent = container.get(FirstParent)
    second_parent = container.get(SecondParent)
    unrelated = container.get(Unrelated)

    assert first_parent is implementation
    assert second_parent is implementation
    assert first_parent.first() == "first"
    assert second_parent.second() == "second"
    assert isinstance(unrelated, Unrelated)

from abc import abstractmethod
from typing import Protocol

from dishka import Provider, Scope, WithParents, make_container, provide_all


class ByteTransformer(Protocol):
    @abstractmethod
    def __call__(self, data: bytes) -> bytes:
        pass


class ReverseTransformer(ByteTransformer):
    def __call__(self, data: bytes) -> bytes:
        return data[::-1]


class BaseService:
    pass


class Capability(Protocol):
    @abstractmethod
    def describe(self) -> str:
        pass


class Service(BaseService, Capability):
    def describe(self) -> str:
        return "service"


class PlainDependency:
    pass


def test_provide_all_with_parents_registers_implementation_and_all_parents():
    class TestProvider(Provider):
        scope = Scope.REQUEST

        dependencies = provide_all(
            WithParents[ReverseTransformer],
            WithParents[Service],
            PlainDependency,
        )

    container = make_container(TestProvider())

    with container() as request_container:
        transformer = request_container.get(ReverseTransformer)
        transformer_protocol = request_container.get(ByteTransformer)
        service = request_container.get(Service)
        base_service = request_container.get(BaseService)
        capability = request_container.get(Capability)
        plain_dependency = request_container.get(PlainDependency)

        assert transformer(b"dishka") == b"akhsid"
        assert transformer_protocol is transformer

        assert service.describe() == "service"
        assert base_service is service
        assert capability is service

        assert isinstance(plain_dependency, PlainDependency)


class FirstProtocol(Protocol):
    @abstractmethod
    def first(self) -> str:
        pass


class FirstImplementation(FirstProtocol):
    def first(self) -> str:
        return "first"


class SecondProtocol(Protocol):
    @abstractmethod
    def second(self) -> str:
        pass


class SecondImplementation(SecondProtocol):
    def second(self) -> str:
        return "second"


def test_provider_instance_provide_all_accepts_multiple_with_parents_sources():
    provider = Provider(scope=Scope.APP)
    provider.provide_all(
        WithParents[FirstImplementation],
        WithParents[SecondImplementation],
    )

    container = make_container(provider)

    first = container.get(FirstImplementation)
    second = container.get(SecondImplementation)

    assert container.get(FirstProtocol) is first
    assert container.get(SecondProtocol) is second
    assert first.first() == "first"
    assert second.second() == "second"

