from typing import Protocol

import pytest

from dishka import Provider, Scope, WithParents, make_container, provide_all


class CallableProtocol(Protocol):
    def __call__(self, data: bytes) -> bytes: ...


class CallableImplementation(CallableProtocol):
    def __call__(self, data: bytes) -> bytes:
        return data[::-1]


class BaseService:
    pass


class DerivedService(BaseService):
    pass


@pytest.mark.parametrize("register_on_instance", [False, True])
def test_provide_all_with_parents_registers_concrete_types_and_parents(
    register_on_instance: bool,
) -> None:
    """``provide_all`` must expand ``WithParents`` just like ``provide`` does."""

    if register_on_instance:
        provider = Provider(scope=Scope.APP)
        provider.provide_all(
            WithParents[CallableImplementation],
            WithParents[DerivedService],
        )
    else:

        class ServicesProvider(Provider):
            scope = Scope.APP

            services = provide_all(
                WithParents[CallableImplementation],
                WithParents[DerivedService],
            )

        provider = ServicesProvider()

    container = make_container(provider)

    implementation = container.get(CallableImplementation)
    protocol = container.get(CallableProtocol)
    derived = container.get(DerivedService)
    base = container.get(BaseService)

    assert isinstance(implementation, CallableImplementation)
    assert implementation(b"dishka") == b"akhsid"

    # WithParents must create aliases rather than separate parent instances.
    assert protocol is implementation
    assert base is derived
    assert isinstance(derived, DerivedService)

