def test_provide_all_with_parents_registers_concrete_class_and_all_parents():
    class Configuration:
        def __init__(self) -> None:
            self.prefix = b"configured:"

    class BaseInteractor:
        pass

    class Interactor(Protocol):
        @abstractmethod
        def __call__(self, data: bytes) -> bytes: ...

    class ConcreteInteractor(BaseInteractor, Interactor):
        def __init__(self, configuration: Configuration) -> None:
            self.configuration = configuration

        def __call__(self, data: bytes) -> bytes:
            return self.configuration.prefix + data

    class InteractorsProvider(Provider):
        scope = Scope.APP
        dependencies = provide_all(
            Configuration,
            WithParents[ConcreteInteractor],
        )

    container = make_container(InteractorsProvider())

    concrete = container.get(ConcreteInteractor)
    as_base = container.get(BaseInteractor)
    as_protocol = container.get(Interactor)

    assert isinstance(concrete, ConcreteInteractor)
    assert concrete(b"value") == b"configured:value"
    assert as_base is concrete
    assert as_protocol is concrete


def test_provider_instance_provide_all_accepts_with_parents():
    class Parent:
        pass

    class Interface(Protocol):
        @abstractmethod
        def value(self) -> str: ...

    class Implementation(Parent, Interface):
        def value(self) -> str:
            return "implemented"

    provider = Provider(scope=Scope.APP)
    provider.provide_all(WithParents[Implementation])

    container = make_container(provider)

    implementation = container.get(Implementation)

    assert implementation.value() == "implemented"
    assert container.get(Parent) is implementation
    assert container.get(Interface) is implementation

