import numpy
import pandas
import pytest
from sklearn.linear_model import LinearRegression

from skore import CrossValidationReporter
from skore.item.cross_validation_aggregation_item import (
    CrossValidationAggregationItem,
)


@pytest.fixture
def regression_data():
    """Small deterministic regression dataset with non-trivial fold scores."""
    X = numpy.arange(18, dtype=float).reshape(-1, 1)
    y = X[:, 0] ** 2 + 0.5 * X[:, 0]
    return X, y


@pytest.mark.parametrize(
    ("scoring", "expected_metrics"),
    [
        (
            ["neg_mean_absolute_error", "r2", "explained_variance"],
            {
                "test_neg_mean_absolute_error",
                "test_r2",
                "test_explained_variance",
            },
        ),
        (("r2",), {"test_r2"}),
    ],
)
def test_aggregated_cross_validation_accepts_sequence_scoring(
    in_memory_project, regression_data, scoring, expected_metrics
):
    """List and tuple scorer inputs must work through project aggregation."""
    X, y = regression_data
    reporter = CrossValidationReporter(
        LinearRegression(), X, y, cv=3, scoring=scoring
    )

    # A second version triggers creation of the aggregate cross-validation
    # result, where the reported failure occurred.
    in_memory_project.put("cross-validation", reporter)
    in_memory_project.put("cross-validation", reporter)

    versions = in_memory_project.get_item_versions("cross-validation")
    aggregation = CrossValidationAggregationItem.factory(versions)

    assert expected_metrics <= {trace.name for trace in aggregation.plot.data}


def _assert_trace_matches_versions(trace, versions, result_key):
    """A metric's values must remain at their original run/fold positions."""
    expected_values = []
    for version in versions:
        results = version.cv_results_serialized
        number_of_folds = len(results["fit_time"])

        if result_key in results:
            expected_values.extend(results[result_key])
        else:
            # This metric was not requested for this entire CV run. Its fold
            # positions must remain empty rather than being filled with a later
            # run's scores.
            expected_values.extend([numpy.nan] * number_of_folds)

    assert len(trace.y) == len(expected_values)

    for actual_value, expected_value in zip(trace.y, expected_values):
        if pandas.isna(expected_value):
            assert pandas.isna(actual_value)
        else:
            assert actual_value == pytest.approx(expected_value)


def test_aggregation_preserves_missing_extra_score_positions(
    in_memory_project, regression_data
):
    """Changing scoring between versions must not shift extra metric values.

    A single-score run is deliberately placed between two runs with extra
    scores. This covers the missing-column case that causes pandas to create
    null values during aggregation.
    """
    X, y = regression_data
    multi_metric_scoring = ["r2", "explained_variance"]

    reporters = [
        CrossValidationReporter(
            LinearRegression(), X, y, cv=3, scoring=multi_metric_scoring
        ),
        CrossValidationReporter(
            LinearRegression(), X, y, cv=3, scoring="r2"
        ),
        CrossValidationReporter(
            LinearRegression(), X, y, cv=3, scoring=multi_metric_scoring
        ),
    ]

    for reporter in reporters:
        in_memory_project.put("cross-validation", reporter)

    versions = in_memory_project.get_item_versions("cross-validation")
    aggregation = CrossValidationAggregationItem.factory(versions)
    traces = {trace.name: trace for trace in aggregation.plot.data}

    assert {"test_score", "test_r2", "test_explained_variance"} <= set(traces)

    _assert_trace_matches_versions(
        traces["test_explained_variance"],
        versions,
        "test_explained_variance",
    )
    _assert_trace_matches_versions(traces["test_score"], versions, "test_score")

from __future__ import annotations

import pytest

from textual.app import App
from textual.widget import Widget


@pytest.mark.parametrize("direction", ("before", "after"))
async def test_move_child_to_itself_is_a_no_op_for_all_reference_forms(
    direction: str,
) -> None:
    """A child may be referred to by either a widget or an equivalent index."""
    async with App().run_test() as pilot:
        children = [Widget(id=f"child-{index}") for index in range(4)]
        container = Widget(*children)
        await pilot.app.mount(container)

        # The third child is at both index 2 and negative index -2.
        references = {
            "widget": children[2],
            "index": 2,
            "negative_index": -2,
        }
        original_children = tuple(container.children)

        for child_reference in references.values():
            for target_reference in references.values():
                if direction == "before":
                    container.move_child(child_reference, before=target_reference)
                else:
                    container.move_child(child_reference, after=target_reference)

                # It must neither raise nor change the order (or identity) of children.
                assert tuple(container.children) == original_children
                assert all(
                    actual is expected
                    for actual, expected in zip(container.children, original_children)
                )

