def test_explicit_parameters_replace_decorator_and_none_is_forwarded(worksheet):
    """Worksheet APIs use normal parameters and preserve None transport values."""
    decorated_methods = (
        Worksheet.get_values,
        Worksheet.get_all_values,
        Worksheet.row_values,
        Worksheet.get,
        Worksheet.batch_get,
        Worksheet.update,
        Worksheet.batch_update,
    )
    for method in decorated_methods:
        assert all(
            parameter.kind is not inspect.Parameter.VAR_KEYWORD
            for parameter in inspect.signature(method).parameters.values()
        )

    with pytest.raises(TypeError):
        worksheet.get("A1", misspelled_option=True)

    worksheet.batch_get(["A1", "B1"])
    _, _, ranges, params = worksheet.client.calls[-1]
    assert ranges == ["'Sheet1'!A1", "'Sheet1'!B1"]
    assert params == {
        "majorDimension": None,
        "valueRenderOption": None,
        "dateTimeRenderOption": None,
    }

    worksheet.update("A1", "new value", raw=False)
    _, _, update_range, update_params, update_body = worksheet.client.calls[-1]
    assert update_range == "'Sheet1'!A1"
    assert update_params == {
        "valueInputOption": utils.ValueInputOption.user_entered,
        "includeValuesInResponse": None,
        "responseValueRenderOption": None,
        "responseDateTimeRenderOption": None,
    }
    assert update_body == {"values": [["new value"]], "majorDimension": None}

    worksheet.batch_update([{"range": "A1", "values": [["new value"]]}])
    _, _, body = worksheet.client.calls[-1]
    assert body == {
        "valueInputOption": utils.ValueInputOption.raw,
        "includeValuesInResponse": None,
        "responseValueRenderOption": None,
        "responseDateTimeRenderOption": None,
        "data": [{"range": "'Sheet1'!A1", "values": [["new value"]]}],
    }

