from lxml import html

from parsel import Selector
import parsel.selector as selector_module


def test_default_encoding_allows_html_css_selection_when_lxml_rejects_utf8(
    monkeypatch,
):
    """The default encoding passed to lxml must be its canonical UTF-8 name."""

    def parser_rejecting_legacy_utf8(*args, **kwargs):
        if kwargs.get("encoding") == "utf8":
            raise LookupError("unknown encoding: 'b'utf8''")
        return html.HTMLParser(*args, **kwargs)

    monkeypatch.setitem(
        selector_module._ctgroup["html"], "_parser", parser_rejecting_legacy_utf8
    )

    selector = Selector(
        body=b"<html><head><title>Tutorial title</title></head></html>"
    )

    assert selector.css("title::text").get() == "Tutorial title"


def test_default_utf8_encoding_still_autodetects_json_bytes():
    """Canonicalizing the default must preserve JSON detection for byte input."""
    selector = Selector(body=b'{"title": "JSON document", "items": [1, 2]}')

    assert selector.type == "json"
    assert selector.jmespath("title").get() == "JSON document"
    assert selector.jmespath("items").getall() == ["1", "2"]


def test_default_encoding_decodes_utf8_html_content():
    selector = Selector(
        body="<html><head><title>café</title></head></html>".encode("utf-8")
    )

    assert selector.css("title::text").get() == "café"

"""Regression tests for lxml-compatible default UTF-8 encoding handling."""

from lxml import html

from parsel import Selector
from parsel import selector as selector_module


class _ParserRejectingUtf8Alias:
    """Model lxml builds which reject the ``utf8`` spelling internally."""

    def __new__(cls, *args, **kwargs):
        if kwargs.get("encoding") == "utf8":
            raise LookupError("unknown encoding: 'b'utf8''")
        return html.HTMLParser(*args, **kwargs)


def test_default_encoding_allows_css_selection_from_html_bytes(monkeypatch) -> None:
    """A normal response-like bytes body must not pass ``utf8`` to lxml."""
    monkeypatch.setitem(
        selector_module._ctgroup["html"],
        "_parser",
        _ParserRejectingUtf8Alias,
    )

    selector = Selector(
        body=b"<html><head><title>Response title</title></head><body /></html>"
    )

    assert selector.css("title::text").get() == "Response title"


def test_default_encoding_allows_css_selection_from_text(monkeypatch) -> None:
    """Tutorial-style text input must use an lxml-compatible default too."""
    monkeypatch.setitem(
        selector_module._ctgroup["html"],
        "_parser",
        _ParserRejectingUtf8Alias,
    )

    selector = Selector(
        text="<html><head><title>Tutorial title</title></head><body /></html>"
    )

    assert selector.css("title::text").get() == "Tutorial title"


def test_canonical_utf8_encoding_extracts_non_ascii_bytes() -> None:
    """The replacement default spelling must still decode UTF-8 page content."""
    selector = Selector(
        body=b"<html><head><title>Caf\xc3\xa9</title></head><body /></html>"
    )

    assert selector.css("title::text").get() == "Café"

