import importlib

import pytest

from parsel import Selector


@pytest.mark.parametrize(
    "selector_kwargs",
    [
        {"text": "<html><head><title>From text</title></head></html>"},
        {"body": b"<html><head><title>From bytes</title></head></html>"},
    ],
)
def test_default_html_encoding_is_portable_for_css_selection(
    monkeypatch, selector_kwargs
):
    """Default parsing must use the canonical UTF-8 spelling accepted by lxml.

    Some lxml builds reject the historical ``utf8`` default.  Simulate such a
    build while exercising the public Selector/CSS API for both supported HTML
    input forms.
    """
    selector_module = importlib.import_module("parsel.selector")
    real_html_parser = selector_module.html.HTMLParser

    def html_parser_requiring_canonical_utf8(*args, **kwargs):
        encoding = kwargs.get("encoding")
        if encoding != "utf-8":
            raise LookupError(f"unknown encoding: {encoding!r}")
        return real_html_parser(*args, **kwargs)

    monkeypatch.setitem(
        selector_module._ctgroup["html"],
        "_parser",
        html_parser_requiring_canonical_utf8,
    )

    selector = Selector(**selector_kwargs)

    assert selector.css("title::text").get() in {"From text", "From bytes"}

