    audience,
):
    token_with_null_aud = make_token({"sub": "user", "aud": None})
    token_without_aud = make_token({"sub": "user"})

    with pytest.raises(MissingRequiredClaimError) as null_aud_error:
        decode_token(token_with_null_aud, audience=audience)

    with pytest.raises(MissingRequiredClaimError) as missing_aud_error:
        decode_token(token_without_aud, audience=audience)

    assert null_aud_error.value.claim == missing_aud_error.value.claim == "aud"

