                    ]

    return expected


@pytest.mark.parametrize(
    "offset,resolution_wh",
    [
        (np.array([-1, -1]), (4, 3)),  # crop top and left edges
        (np.array([-2, 1]), (4, 3)),  # negative x and positive y
        (np.array([1, -1]), (3, 2)),  # negative y and a smaller output
        (np.array([2, 2]), (4, 3)),  # positive movement also crops at bottom/right
    ],
)
def test_move_masks_translates_in_both_directions_with_cropping(
    offset: np.ndarray, resolution_wh: tuple[int, int]
) -> None:
    masks = np.array(
        [
            [
                [True, False, True, False],
                [False, True, False, True],
                [True, True, False, False],
            ],
            [
                [False, True, False, True],
                [True, False, True, False],
                [False, False, True, True],
            ],
        ],
        dtype=bool,
    )
    original_masks = masks.copy()

    result = sv.move_masks(
        masks=masks,
        offset=offset,
        resolution_wh=resolution_wh,
    )

    expected = _expected_translated_masks(masks, offset, resolution_wh)
    np.testing.assert_array_equal(result, expected)
    assert result.shape == (masks.shape[0], resolution_wh[1], resolution_wh[0])
    assert result.dtype == np.bool_
    np.testing.assert_array_equal(masks, original_masks)


