from starlette.datastructures import MutableHeaders


def test_mutable_headers_ior_merges_dict_in_place_and_normalizes_keys():
    headers = MutableHeaders(
        raw=[
            (b"x-header", b"first"),
            (b"x-header", b"duplicate"),
            (b"keep", b"value"),
        ]
    )
    alias = headers

    headers |= {"X-Header": "replacement", "X-New": "new"}

    assert headers is alias
    assert headers.raw == [
        (b"x-header", b"replacement"),
        (b"keep", b"value"),
        (b"x-new", b"new"),
    ]
    assert headers.getlist("x-header") == ["replacement"]
    assert headers["X-HEADER"] == "replacement"
    assert dict(headers) == {
        "x-header": "replacement",
        "keep": "value",
        "x-new": "new",
    }


def test_mutable_headers_or_merges_dict_without_mutating_original():
    headers = MutableHeaders({"Existing": "original"})

    merged = headers | {"X-Header": "string", "EXISTING": "updated"}

    assert isinstance(merged, MutableHeaders)
    assert merged is not headers

    # `|` has dictionary merge semantics: it leaves the left operand unchanged.
    assert dict(headers) == {"existing": "original"}

    # Values supplied by the right-hand dictionary replace matching headers,
    # regardless of header-key casing.
    assert dict(merged) == {"existing": "updated", "x-header": "string"}
    assert repr(merged) == "MutableHeaders({'existing': 'updated', 'x-header': 'string'})"

