def test_mutable_headers_ior_matches_update_for_multiple_headers():
    expected = MutableHeaders({"Existing": "value"})
    actual = MutableHeaders({"Existing": "value"})
    updates = {"X-One": "one", "X-Two": "two", "existing": "replacement"}

    expected.update(updates)
    actual |= updates

    assert actual.items() == expected.items()
    assert dict(actual) == {
        "existing": "replacement",
        "x-one": "one",
        "x-two": "two",
    }


def test_mutable_headers_or_returns_independent_merged_copy():
    original = MutableHeaders(
        raw=[(b"x-header", b"first"), (b"x-header", b"duplicate"), (b"keep", b"value")]
    )

    merged = original | {"X-Header": "replacement", "X-New": "new"}

    assert isinstance(merged, MutableHeaders)
    assert merged is not original
    assert merged.items() == [
        ("x-header", "replacement"),
        ("keep", "value"),
        ("x-new", "new"),
    ]
    # Non-in-place merging must not alter the source, including its duplicates.
    assert original.items() == [
        ("x-header", "first"),
        ("x-header", "duplicate"),
        ("keep", "value"),
    ]


def test_mutable_headers_operators_accept_another_mutable_headers():
    source = MutableHeaders({"X-Source": "source"})
    target = MutableHeaders({"X-Target": "target"})

    target |= source

    assert dict(target) == {"x-target": "target", "x-source": "source"}

    merged = source | MutableHeaders({"X-Other": "other"})
    assert dict(merged) == {"x-source": "source", "x-other": "other"}
    assert dict(source) == {"x-source": "source"}

